dtsPropsFor.AccountRow:
account: { /** Stake account address (base58). */ address: string; lamports: bigint; lockup: { /** Lock end, unix seconds; 0 = no lock. */ unixTimestamp: bigint; epoch: bigint; /** The Second key that holds the lock (base58). */ custodian: string } };
activation: "inactive" | "activating" | "active" | "deactivating";
/** From core `scannerStatus`. */
protection: "unprotected" | "protected" | "expiring" | "locked-by-other";
/** From core `scannerStatus`: staker != withdrawer. Without a lock of the viewer's second key a service may manage the stak */
managedByService: boolean;
/** This browser knows a second key for the account's main key: the list core `scannerStatus` got was not empty. With one, a */
secondKeyKnown: boolean;
/** F6: this account was protected and its lock is gone. With `protection: 'unprotected'` its badge is red. */
wasProtected?: boolean;
/** Rescue for this account's main key (`/rescue?address=`): linked from the stake-key warning. Left out on the rescue pages */
rescueHref?: string;
/** The cluster clock the statuses were computed with. A lock that ends within 30 days of it (core's Expiring threshold) sho */
clock: { /** Cluster time, unix seconds. */ unixTimestamp: bigint; epoch: bigint };
/** The one visible button: `<Button variant="outline" size="sm">`, primary only when it is the screen's one filled button ( */
action?: React.ReactNode;
/** Every other action (Withdraw, Recovery card, ...): behind the row's More, which opens them under the row. */
moreActions?: React.ReactNode;
/** More starts open (the /dev/ui sample of an open row). */
defaultMoreOpen?: boolean;
/** A selection checkbox at the start of the row, named by `label`. */
select?: { checked: boolean; onCheckedChange: (checked: boolean) => void; label: string; disabled?: boolean | undefined; };
/** More muted facts on the second line. An address in it is always an AddressText (copy and explorer), e.g. "Main key" and  */
meta?: React.ReactNode;
/** The status hint sentence under the row; default true. A list that says it once for its group passes false. */
hint?: boolean;
/** The second sentence of the staking-service warning, what a lock may do to the service; default false. */
serviceDetail?: boolean;
className?: string;

dtsPropsFor.CosignRequest:
/** The link's transaction kind (`data-kind`): protect, withdraw or rescue. */
kind: string;
/** Who sent it: the role of the fee payer, who signed before the link was made. */
from: "main" | "second" | "new";
/** The h2, the ask in one line: "Become the Second key for this stake until 3 April 2027". */
ask: string;
/** One to three short lines under the ask. */
lines?: readonly string[];
/** One muted line, e.g. how much the stake account holds once it is read. */
meta?: React.ReactNode;
/** The check before signing, a warning callout with the address in full. */
check?: { title: string; lines: readonly string[]; /** The role of the address to check. */ role: "main" | "second" | "new"; /** The address, shown in full. */ address: string };
className?: string;

dtsPropsFor.EmptyState:
icon?: React.ComponentType<{ className?: string }> /* a lucide-react icon, e.g. LayersIcon */;
title: string;
headingLevel?: 2 | 3;
/** Explanation: why it is empty and what the user can do (UX rule 13). */
children?: React.ReactNode;
/** Next step, e.g. a button to check another address. */
action?: React.ReactNode;
className?: string;

dtsPropsFor.JobStatusList:
items: readonly { /** The stake account (base58). */ address: string; status: "waiting" | "sending" | "confirming" | "checking" | "done" | "failed" | "expired" | "unknown" | "not-sent" | "left-out"; /** What happened and what to do next, in plain words. */ reason?: string; /** Original error text, under "Details". */ detail?: string; /** The transaction signature once known (explorer link). */ signature?: string | null }[];
/** Accessible name of the list, e.g. "Stake accounts". */
