className?: string;

dtsPropsFor.LinkCard:
/** The /cosign link (the partly signed transaction in its fragment). */
url: string;
/** The transaction id (the fee payer's signature): the explorer shows it once the other device sends it. */
signature: string;
/** The keys that sign through the link, in signing order; shown in full (DECISIONS.md D23). */
signers: readonly { role: "main" | "second" | "new"; address: string; }[];
/** This page is checking the network for the outcome; false once the watch paused. */
watching: boolean;
/** The latest check could not reach the network (it keeps trying). */
lastCheckFailed: boolean;
/** Stop waiting on this page (the link keeps working). Without it the card shows no Stop button. */
onStopWaiting?: () => void;
/** A new watch after the pause. Without it the paused card offers no Check again. */
onCheckAgain?: () => void;
/** The page's way to cancel the link (closing the link-signing account), shown inline under "Cancel the link". It stays mou */
cancel?: React.ReactNode;
className?: string;

dtsPropsFor.RadioCardGroup:
legend: string;
/** The legend only for screen readers, when a heading right above says the same. */
legendHidden?: boolean;
value: string;
onValueChange: (value: string) => void;
options: readonly { value: string; /** The option's name (its accessible name). */ title: string; /** One muted line, e.g. "until 10 April 2027". */ meta?: React.ReactNode; /** e.g. <Badge tone="success">Recommended</Badge>. */ badge?: React.ReactNode; description?: string; /** danger: an option that removes protection, set apart after a separator. */ tone?: "default" | "danger"; /** Why it cannot be chosen; disables the option. */ disabledReason?: string }[];
/** 2: two columns from 640 px. */
columns?: 1 | 2;
className?: string;

dtsPropsFor.SignerList:
items: readonly { role: "main" | "second" | "new"; /** The wallet app holding this key here; null when none offers it. */ walletName: string | null; address: string; /** Transactions this key approves in its one request. */ count: number; status: "waiting" | "current" | "signed" | "switch" | "stopped" | "missing" | "link" }[];
/** `full` (default): a card per key with its full address. `compact`: one line per key, its number, role, wallet and status */
variant?: "full" | "compact";
className?: string;

dtsPropsFor.StopPanel:
/** The h2: "Do not sign this link". */
title: string;
/** Why, in one line. */
reason: React.ReactNode;
/** Addresses the reason is about, labelled and in full (DECISIONS.md D23): where the SOL would go, whose stake it is. */
addresses?: readonly { label: string; /** Shown in full. */ address: string }[];
/** "What to do: ..." when the link may come from a thief. */
whatToDo?: string;
/** The inspector's own words, under Details (UX rule 8). */
detail?: string;
/** The one way out, an outline button ("Back to the start page"). */
action?: React.ReactNode;
/** Pages that move focus to the panel's heading when it replaces what was there. */
headingRef?: React.Ref<HTMLHeadingElement>;
/** What the panel refuses, for tests and styling hooks (`data-reason`). */
reasonCode?: string;
className?: string;

dtsPropsFor.TransactionSummary:
/** From core `inspectTransaction(bytes)` on the exact bytes about to be signed (CLAUDE.md section 3). */
summary: {
  /** What the transaction does. */
  action:
  | { kind: "protect"; stakeAccount: string; mainKey: string; secondKey: string; /** unix seconds */ lockUntil: bigint }
  | { kind: "extend"; stakeAccount: string; secondKey: string; lockUntil: bigint }
  | { kind: "unlock"; stakeAccount: string; secondKey: string }
  | { kind: "withdraw"; stakeAccount: string; mainKey: string; secondKey: string | null; recipient: string; lamports: bigint }
  | { kind: "deactivate"; stakeAccount: string; staker: string }
  | { kind: "delegate"; stakeAccount: string; staker: string; voteAccount: string }
  | { kind: "rescue"; stakeAccount: string; mainKey: string; secondKey: string; newWallet: string }
  | { kind: "nonce-setup"; nonceAccount: string; nonceAuthority: string; seed: string; lamports: bigint }
  | { kind: "nonce-close"; nonceAccount: string; nonceAuthority: string; recipient: string; lamports: bigint };
  feePayer: string;
  lifetime: { kind: "blockhash"; blockhash: string } | { kind: "nonce"; nonceAccount: string; nonceAuthority: string; nonceValue: string };
  computeBudget: { unitLimit: number; microLamportsPerUnit: bigint };
  /** Upper bound of the network fee in lamports. */
  networkFeeLamports: bigint;
  /** Every address that must sign, fee payer first. */
  requiredSigners: readonly string[];
  /** Required signers whose signature is already present and valid. */
  presentSignatures: readonly string[];
  /** Lighthouse assertions a wallet appended, or null. */
  lighthouseTail: { instructionCount: number; addedAccounts: readonly string[] } | null;
};
/** Ignored with `batch`: each account there carries its own. */
current?: { lockup: { /** Lock end, unix seconds; 0 = no lock. */ unixTimestamp: bigint; epoch: bigint; /** The Second key that holds the lock (base58). */ custodian: string }; clock?: { /** Cluster time, unix seconds. */ unixTimestamp: bigint; epoch: bigint } };
/** Addresses the page knows by role (its wallet slots), to name signers the action itself does not name. */
knownRoles?: Partial<Record<"main" | "second" | "new", string>>;
/** Several transactions summarised at once: the stake account block becomes the list of accounts (each with its balance and */
batch?: { accounts: readonly { address: string; lamports: bigint | null; current?: { lockup: { /** Lock end, unix seconds; 0 = no lock. */ unixTimestamp: bigint; epoch: bigint; /** The Second key that holds the lock (base58). */ custodian: string }; clock?: { /** Cluster time, unix seconds. */ unixTimestamp: bigint; epoch: bigint } } }[]; totalFeeLamports: bigint };
/** The line under the title that says the summary is read from the bytes; /cosign leaves it out (default true). */
intro?: boolean;
headingLevel?: 2 | 3;
className?: string;

dtsPropsFor.TransactionSummaryError:
error: { code: "malformed" | "unsupported-version" | "address-lookup-table" | "unknown-program" | "unknown-instruction" | "bad-layout" | "multiple-stake-accounts" | "bad-lighthouse-tail" | "invalid-signature" | "verification-unavailable"; /** Plain English for "Details". */ message: string };
headingLevel?: 2 | 3;
/** The way forward, e.g. "Back to your accounts". */
action?: React.ReactNode;
className?: string;
